#include <iostream>
#include <string>

int main() {
    std::string inputLine;
    std::getline(std::cin, inputLine);
    int insertionsNeeded = 0;
    int currentSequenceCount = 1;
    for (size_t index = 0; index + 1 < inputLine.length(); ++index) {
        if (inputLine[index] == inputLine[index + 1]) {
            ++currentSequenceCount;
        } else {
            if (currentSequenceCount % 2 == 0) {
                ++insertionsNeeded;
            }
            currentSequenceCount = 1;
        }
    }
    if (currentSequenceCount % 2 == 0) {
        ++insertionsNeeded;
    }
    std::cout << insertionsNeeded << std::endl;
    return 0;
}
